<?php
namespace App\Http\Controllers; use App\Models\{Task,TaskMember}; use Illuminate\Http\Request;
class TaskMemberController extends Controller { private function own(Task $t){abort_unless($t->user_id===auth()->id(),403);} public function store(Request $r,Task $task){$this->own($task);$d=$r->validate(['user_id'=>'required|exists:users,id','member_status'=>'required|in:pending,accepted,rejected']);TaskMember::updateOrCreate(['task_id'=>$task->id,'user_id'=>$d['user_id']],['member_status'=>$d['member_status'],'joined_at'=>now()]);return back()->with('success','Anggota ditambahkan.');} public function destroy(Task $task,$userId){$this->own($task);TaskMember::where('task_id',$task->id)->where('user_id',$userId)->delete();return back()->with('success','Anggota dihapus.');} }
